solution:
import numpy as np


def normalize(gray, m0=128.0, s0=50.0):
    g = np.asarray(gray, dtype=float)
    std = g.std()
    if std == 0:
        return np.full(g.shape, m0, dtype=float)
    return (g - g.mean()) / std * s0 + m0
